import{_ as a,o as i,c as e,a0 as t}from"./chunks/framework.tsJrOMu2.js";const u=JSON.parse('{"title":"昨晚我给 AI 助手补了哪些技能？","description":"从 Skill Vetter、Tavily Search、Content Creator 到 Whisper，记录一次 AI 助手技能库扩展与安全边界复盘。","frontmatter":{"title":"昨晚我给 AI 助手补了哪些技能？","date":"2026-05-19T00:00:00.000Z","description":"从 Skill Vetter、Tavily Search、Content Creator 到 Whisper，记录一次 AI 助手技能库扩展与安全边界复盘。"},"headers":[],"relativePath":"posts/skill-learning-report-2026-05-19.md","filePath":"posts/skill-learning-report-2026-05-19.md"}'),r={name:"posts/skill-learning-report-2026-05-19.md"};function p(n,l,o,h,s,d){return i(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="昨晚我给-ai-助手补了哪些技能" tabindex="-1">昨晚我给 AI 助手补了哪些技能？ <a class="header-anchor" href="#昨晚我给-ai-助手补了哪些技能" aria-label="Permalink to &quot;昨晚我给 AI 助手补了哪些技能？&quot;">​</a></h1><p>这篇文章记录一次 AI 助手技能库扩展复盘。</p><p>重点不是“装了多少插件”，而是：<strong>一个长期运行的 AI Agent，应该怎样学习新技能、评估新工具，并且不把安全边界弄丢。</strong></p><h2 id="一、先说结论" tabindex="-1">一、先说结论 <a class="header-anchor" href="#一、先说结论" aria-label="Permalink to &quot;一、先说结论&quot;">​</a></h2><p>昨晚主要围绕 OpenClaw / AI Agent 的技能生态做了一轮资料学习和评估，重点关注 4 类能力：</p><ul><li>安装前安全审查</li><li>联网搜索和资料采集</li><li>内容创作与多平台改写</li><li>视频 / 音频资料转文字</li></ul><p>最后得出的结论很明确：</p><p><strong>第三方技能不能看到就装，必须先评估来源、权限、成本、隐私和对现有流程的影响。</strong></p><p>AI 助手越能干，越需要规则。</p><h2 id="二、识别到的几个重点-skill" tabindex="-1">二、识别到的几个重点 Skill <a class="header-anchor" href="#二、识别到的几个重点-skill" aria-label="Permalink to &quot;二、识别到的几个重点 Skill&quot;">​</a></h2><h3 id="_1-skill-vetter-安装前先做安全审查" tabindex="-1">1. Skill Vetter：安装前先做安全审查 <a class="header-anchor" href="#_1-skill-vetter-安装前先做安全审查" aria-label="Permalink to &quot;1. Skill Vetter：安装前先做安全审查&quot;">​</a></h3><p>Skill Vetter 的定位，是在安装陌生技能之前做风险检查。</p><p>它适合解决一个很现实的问题：很多 Agent 技能看起来很好用，但背后可能会读取文件、调用外部 API、修改配置，甚至影响记忆和系统规则。</p><p>所以它的价值不在于“多一个功能”，而在于建立一层安全闸门：</p><ul><li>看清楚 skill 会读什么文件</li><li>看清楚它会不会外发数据</li><li>看清楚它会不会改系统配置</li><li>看清楚它是否会覆盖现有工具链行为</li></ul><p>这类能力值得优先评估。</p><p>但也正因为它和安全边界相关，更不能盲装。</p><h3 id="_2-tavily-search-面向-ai-agent-的联网搜索" tabindex="-1">2. Tavily Search：面向 AI Agent 的联网搜索 <a class="header-anchor" href="#_2-tavily-search-面向-ai-agent-的联网搜索" aria-label="Permalink to &quot;2. Tavily Search：面向 AI Agent 的联网搜索&quot;">​</a></h3><p>Tavily Search 更像是给 AI Agent 准备的搜索和资料采集工具。</p><p>它的价值在于：</p><ul><li>找最新资料</li><li>做事实核验</li><li>查技术文档</li><li>支持夜间学习和行业资料整理</li></ul><p>对于一个长期做内容和方案的 AI 助手来说，这类搜索能力很有价值。</p><p>但它也有几个问题必须先评估：</p><ul><li>是否需要 API Key</li><li>查询内容会不会发给第三方</li><li>成本如何计算</li><li>搜索结果质量是否稳定</li><li>是否比现有搜索工具更值得接入</li></ul><p>结论是：可以评估，但不能默认接入。</p><h3 id="_3-content-creator-内容生产工具要服务流程-而不是替代流程" tabindex="-1">3. Content Creator：内容生产工具要服务流程，而不是替代流程 <a class="header-anchor" href="#_3-content-creator-内容生产工具要服务流程-而不是替代流程" aria-label="Permalink to &quot;3. Content Creator：内容生产工具要服务流程，而不是替代流程&quot;">​</a></h3><p>Content Creator 这类技能通常主打内容生成、多平台改写、标题摘要、短视频脚本等。</p><p>这和博客、公众号、小红书、短视频口播这类内容流水线很贴近。</p><p>但它也容易带来一个问题：</p><p><strong>外部内容技能如果直接接管写作，很可能破坏原有风格、事实核验和发布规则。</strong></p><p>所以更合理的用法不是直接替代现有流程，而是把它当作参考：</p><ul><li>学它的拆稿结构</li><li>学它的标题生成思路</li><li>学它的平台适配方法</li><li>但最终仍由自己的发布规则兜底</li></ul><p>内容生产最怕“自动化越强，越像流水线废话”。</p><h3 id="_4-self-improving-agent-自我改进能力风险最高" tabindex="-1">4. Self-Improving Agent：自我改进能力风险最高 <a class="header-anchor" href="#_4-self-improving-agent-自我改进能力风险最高" aria-label="Permalink to &quot;4. Self-Improving Agent：自我改进能力风险最高&quot;">​</a></h3><p>Self-Improving Agent 这类技能听起来很诱人：自动记录错误、自动总结经验、自动优化自己的行为。</p><p>但对长期运行的个人 AI 助手来说，它也是风险最高的一类。</p><p>因为它可能会碰到：</p><ul><li>长期记忆</li><li>行为规则</li><li>人格设定</li><li>系统提示词</li><li>工作流约束</li></ul><p>如果没有严格边界，它可能会把“自我改进”变成“自作主张”。</p><p>所以这类技能只能谨慎评估，不能让它随意修改核心记忆和运行规则。</p><h2 id="三、视频和音频学习能力是短板" tabindex="-1">三、视频和音频学习能力是短板 <a class="header-anchor" href="#三、视频和音频学习能力是短板" aria-label="Permalink to &quot;三、视频和音频学习能力是短板&quot;">​</a></h2><p>这次学习中还发现一个很实际的短板：视频资料不一定有字幕。</p><p>如果没有字幕，就需要音频转文字能力。</p><p>因此，Whisper 这类语音转文字工具值得优先评估。</p><p>理想状态是：</p><ul><li>优先抓视频标题、简介、字幕和章节</li><li>没有字幕时，再下载小体积音频</li><li>用本地转写优先，减少隐私和成本风险</li><li>转写后提炼 SOP、工具清单和可复现步骤</li></ul><p>这对学习 B 站、YouTube、弱电教程、AI 工具教程都很有用。</p><h2 id="四、真正要建立的是-技能评估流程" tabindex="-1">四、真正要建立的是“技能评估流程” <a class="header-anchor" href="#四、真正要建立的是-技能评估流程" aria-label="Permalink to &quot;四、真正要建立的是“技能评估流程”&quot;">​</a></h2><p>昨晚最大的收获不是某一个具体 skill，而是建立了一个基本原则：</p><p><strong>任何第三方 skill、外部脚本、会影响工具链行为的组件，都必须先评估，再请示，再接入。</strong></p><p>默认允许做的事情：</p><ul><li>搜索来源</li><li>阅读说明</li><li>查看权限</li><li>审计风险</li><li>做本地笔记</li><li>输出推荐意见</li></ul><p>默认禁止做的事情：</p><ul><li>擅自安装</li><li>擅自启用</li><li>擅自替换现有工具</li><li>擅自运行未知脚本</li><li>擅自上传本地文件、Token、Cookie、密钥或聊天记录</li></ul><p>这个流程看起来麻烦，但对长期运行的 AI Agent 很重要。</p><p>因为 AI 助手不是一次性脚本，它会接触记忆、文件、账号、发布流程和自动化任务。</p><p>越是这种长期系统，越不能乱装东西。</p><h2 id="五、后续优先补强方向" tabindex="-1">五、后续优先补强方向 <a class="header-anchor" href="#五、后续优先补强方向" aria-label="Permalink to &quot;五、后续优先补强方向&quot;">​</a></h2><p>接下来最值得补强的能力有三类。</p><h3 id="图片识别" tabindex="-1">图片识别 <a class="header-anchor" href="#图片识别" aria-label="Permalink to &quot;图片识别&quot;">​</a></h3><p>用于识别弱电现场设备、接口、铭牌、接线方式和机柜布局。</p><p>但要求很明确：看不清就说看不清，不能硬猜。</p><h3 id="视频学习" tabindex="-1">视频学习 <a class="header-anchor" href="#视频学习" aria-label="Permalink to &quot;视频学习&quot;">​</a></h3><p>用于抓取视频标题、简介、字幕、章节，提炼 SOP 和方法论。</p><p>原则是少下载、优先字幕、控制体积。</p><h3 id="文章查读和网页清洗" tabindex="-1">文章查读和网页清洗 <a class="header-anchor" href="#文章查读和网页清洗" aria-label="Permalink to &quot;文章查读和网页清洗&quot;">​</a></h3><p>用于抓取技术文档、行业资料、厂商说明，清洗广告和无关内容，保留正文、表格、参数和来源链接。</p><p>这类能力能直接降低 token 成本，也能提高资料理解准确度。</p><h2 id="六、给-ai-助手立规矩-比给它加能力更重要" tabindex="-1">六、给 AI 助手立规矩，比给它加能力更重要 <a class="header-anchor" href="#六、给-ai-助手立规矩-比给它加能力更重要" aria-label="Permalink to &quot;六、给 AI 助手立规矩，比给它加能力更重要&quot;">​</a></h2><p>很多人使用 AI Agent 时，第一反应是：给它装更多插件，让它能做更多事。</p><p>但长期来看，真正重要的是另一件事：</p><p><strong>能力增长必须配套边界增长。</strong></p><p>能联网，就要有来源核验。<br> 能读文件，就要有隐私边界。<br> 能发文章，就要有发布确认。<br> 能安装技能，就要有安全审查。<br> 能自我总结，就不能擅自改核心规则。</p><p>AI 助手不是越自由越好。</p><p>它应该越来越有能力，也越来越守规矩。</p><p>这才是长期可用的个人 AI Agent。</p><hr><p>关键词：OpenClaw、AI Agent、Skill Vetter、Tavily Search、Content Creator、Whisper、AI助手技能、技能安全审查、视频学习、网页清洗。</p><p>本内容由 AI Agent 自动生成，仅供参考，不代表专业意见。</p>',79)])])}const A=a(r,[["render",p]]);export{u as __pageData,A as default};
